def create_missing_tipounidade(apps, schema_editor):
    Unidade = apps.get_model("home", "Unidade")
    TipoUnidade = apps.get_model("home", "TipoUnidade")

    # Obter todos os tipos únicos usados na tabela home_unidade
    tipos_usados = Unidade.objects.values_list("tipo", flat=True).distinct()

    for tipo in tipos_usados:
        if tipo and not TipoUnidade.objects.filter(id=tipo).exists():
            TipoUnidade.objects.create(id=tipo, descricao=f"{tipo}")

    # Criar o tipo padrão se não existir
    default_tipo, created = TipoUnidade.objects.get_or_create(id="D", defaults={"descricao": "Default"})


