    Unidade = apps.get_model("home", "Unidade")
    TipoUnidade = apps.get_model("home", "TipoUnidade")
    default_tipo = TipoUnidade.objects.get(id="D")
    Unidade.objects.filter(tipo__isnull=True).update(tipo=default_tipo.id)
    Unidade.objects.exclude(tipo__in=TipoUnidade.objects.values_list("id", flat=True)).update(tipo=default_tipo.id)


